// 1. 创建虚拟线程
Thread vThread = Thread.ofVirtual().start(() -> {
    System.out.println("Running in virtual thread: " + Thread.currentThread());
});
vThread.join();

// 2. 每任务一线程模式（推荐）
try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    for (int i = 0; i < 100_000; i++) {
        int taskId = i;
        executor.submit(() -> {
            // 模拟 I/O 操作
            Thread.sleep(Duration.ofSeconds(1));
            return "Result-" + taskId;
        });
    }
} // 自动关闭并等待所有任务完成

// 3. 注意：避免 synchronized 中的阻塞操作
// 不推荐
synchronized (lock) {
    httpClient.send(request, bodyHandler); // 阻塞 I/O 导致 pinning
}
// 推荐
ReentrantLock reentrantLock = new ReentrantLock();
reentrantLock.lock();
try {
    httpClient.send(request, bodyHandler);
} finally {
    reentrantLock.unlock();
}

// 4. 与传统线程池对比
// 传统方式：受限于线程池大小
ExecutorService pool = Executors.newFixedThreadPool(200); // 最多200并发
// 虚拟线程：轻松支持高并发
ExecutorService vPool = Executors.newVirtualThreadPerTaskExecutor(); // 无上限
